mapper.update:
update oorder
set cons_name  = #{consName},
    cons_addre = #{consAddre}
where order_id = #{orderId}
  and cons_phone = #{consPhone}

mapper.delete:
delete from oorder
where order_id = #{orderId}
  and cons_phone = #{consPhone}

mapper.select:
select cons_phone
from oorder
where order_id = #{orderId}
